ALTER TYPE "MembershipRole" ADD VALUE IF NOT EXISTS 'MODERATOR';
ALTER TYPE "MembershipRole" ADD VALUE IF NOT EXISTS 'FINANCE';
ALTER TYPE "MembershipRole" ADD VALUE IF NOT EXISTS 'VIEWER';
CREATE TABLE "SubscriptionPlan" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"slug" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"priceInCents" BIGINT NOT NULL,"benefits" JSONB NOT NULL DEFAULT '[]',"published" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SubscriptionPlan_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CreatorSubscription" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"planId" UUID NOT NULL,"supporterName" TEXT NOT NULL,"supporterEmail" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"currentPeriodStart" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"currentPeriodEnd" TIMESTAMP(3) NOT NULL,"cancelAtPeriodEnd" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CreatorSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SubscriptionRenewal" ("id" UUID NOT NULL,"subscriptionId" UUID NOT NULL,"amountInCents" BIGINT NOT NULL,"periodStart" TIMESTAMP(3) NOT NULL,"periodEnd" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'MOCK_PAID',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SubscriptionRenewal_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TeamInvite" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"email" TEXT NOT NULL,"role" "MembershipRole" NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"acceptedAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TeamInvite_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ApiToken" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"name" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"tokenPrefix" TEXT NOT NULL,"scopes" TEXT[],"expiresAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"lastUsedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ApiToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebhookEndpoint" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"url" TEXT NOT NULL,"secretHash" TEXT NOT NULL,"events" TEXT[],"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "WebhookEndpoint_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationConnection" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"provider" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'MOCK_CONNECTED',"displayName" TEXT,"configuration" JSONB NOT NULL DEFAULT '{}',"connectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"revokedAt" TIMESTAMP(3),CONSTRAINT "IntegrationConnection_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SubscriptionPlan_organizationId_slug_key" ON "SubscriptionPlan"("organizationId","slug"); CREATE INDEX "SubscriptionPlan_organizationId_published_idx" ON "SubscriptionPlan"("organizationId","published"); CREATE INDEX "CreatorSubscription_organizationId_status_idx" ON "CreatorSubscription"("organizationId","status"); CREATE INDEX "CreatorSubscription_supporterEmail_createdAt_idx" ON "CreatorSubscription"("supporterEmail","createdAt"); CREATE INDEX "SubscriptionRenewal_subscriptionId_createdAt_idx" ON "SubscriptionRenewal"("subscriptionId","createdAt"); CREATE UNIQUE INDEX "TeamInvite_tokenHash_key" ON "TeamInvite"("tokenHash"); CREATE INDEX "TeamInvite_organizationId_email_idx" ON "TeamInvite"("organizationId","email"); CREATE UNIQUE INDEX "ApiToken_tokenHash_key" ON "ApiToken"("tokenHash"); CREATE INDEX "ApiToken_organizationId_revokedAt_idx" ON "ApiToken"("organizationId","revokedAt"); CREATE INDEX "WebhookEndpoint_organizationId_enabled_idx" ON "WebhookEndpoint"("organizationId","enabled"); CREATE UNIQUE INDEX "IntegrationConnection_organizationId_provider_key" ON "IntegrationConnection"("organizationId","provider");
ALTER TABLE "SubscriptionPlan" ADD CONSTRAINT "SubscriptionPlan_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CreatorSubscription" ADD CONSTRAINT "CreatorSubscription_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CreatorSubscription" ADD CONSTRAINT "CreatorSubscription_planId_fkey" FOREIGN KEY ("planId") REFERENCES "SubscriptionPlan"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SubscriptionRenewal" ADD CONSTRAINT "SubscriptionRenewal_subscriptionId_fkey" FOREIGN KEY ("subscriptionId") REFERENCES "CreatorSubscription"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TeamInvite" ADD CONSTRAINT "TeamInvite_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ApiToken" ADD CONSTRAINT "ApiToken_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "WebhookEndpoint" ADD CONSTRAINT "WebhookEndpoint_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "IntegrationConnection" ADD CONSTRAINT "IntegrationConnection_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
